def has_pair_sum(nums, target):
    seen = set()

    for num in nums:
        complement = target - num
        if complement in seen:
            return True
        seen.add(num)

    return False

def reverse_string(s):
    chars = []
    for i in range(len(s) - 1, -1, -1):
        chars.append(s[i])
    return "".join(chars)

def largest_value(nums):
    best = nums[0]
    for num in nums[1:]:
        if num > best:
            best = num
    return best
